import { createHash } from "node:crypto";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname } from "node:path";
import { validateReceipt, encodeReceipt } from "../../../tools/receipt-bridge/receipt.mjs";
import { fixture, JOB } from "../../../tools/receipt-bridge/test/fixtures.mjs";

// These synthetic cases are generated by the existing authoritative JS contract.
// Tests compare the native implementation with these checked-in golden values.
const valid = [];
const invalid = [];
function good(name, mutate = () => {}) {
  const input = fixture();
  mutate(input);
  const normalizedJson = JSON.stringify(validateReceipt(input));
  const result = {
    name, input, normalizedJson,
    fingerprint: createHash("sha256").update(normalizedJson).digest("hex"),
  };
  try { result.text = encodeReceipt(input, { columns: 32 }).text; }
  catch (error) { result.renderError = error.code; }
  valid.push(result);
}
function bad(name, mutate) {
  const input = fixture();
  mutate(input);
  try { validateReceipt(input); }
  catch (error) { invalid.push({ name, input, error: error.code }); return; }
  throw new Error(`Invalid fixture unexpectedly accepted: ${name}`);
}

good("legacy-curbside");
good("numbered-cash-meal-named-bags", (r) => {
  r.orderNumber = "9223372036854775807";
  r.paymentMethod = "cash";
  r.packingPlan.bags[0].name = "Amer";
  r.packingPlan.bags[1].name = "Jay";
  r.items[0].mealComponents = [
    { slot: "main", name: "Cruncher", quantityPerParent: 1, replacement: false },
    { slot: "side", name: "King of Hearts loaded fries", quantityPerParent: 1, replacement: true },
    { slot: "drink", name: "Mango Mirage", quantityPerParent: 1, replacement: true },
  ];
});
good("pickup-one-bag-no-cutlery", (r) => {
  r.fulfilment = "pickup"; r.car = null;
  r.cutleryRequested = false; r.packingPlan.cutleryRequested = false;
  r.packingPlan.separateBags = false;
  r.packingPlan.bags = [{ number: 1, allocations: r.items.map((item) => ({ lineId: item.lineId, quantity: item.quantity })) }];
  r.orderNumber = "0001";
  r.paymentMethod = "card";
});
