bad("price-does-not-include-choices", (r) => { r.items[0].unitPence = 449; });
bad("total-mismatch", (r) => { r.totalPence++; });
bad("unknown-packing-line", (r) => { r.packingPlan.bags[0].allocations[0].lineId = "unknown"; });
bad("duplicate-packing-allocation", (r) => { r.packingPlan.bags[0].allocations.push(r.packingPlan.bags[0].allocations[0]); });
bad("attached-extra-in-wrong-bag", (r) => { r.packingPlan.bags[0].allocations[1].quantity = 2; });
bad("wrong-numbered-bag", (r) => { r.packingPlan.bags[0].number = 2; });
bad("cutlery-mismatch", (r) => { r.packingPlan.cutleryRequested = false; });
bad("unresolved-copy-missing-parent", (r) => { r.copyNumber = 2; r.reprintReason = "Paper roll"; });
bad("original-with-reprint-reason", (r) => { r.reprintReason = "Unexpected"; });
bad("control-character", (r) => { r.items[0].notes = "No onions\u001b@"; });
bad("bidi-invisible-character", (r) => { r.customerName = "A\u202eB"; });
bad("packing-name-noncanonical-spaces", (r) => { r.packingPlan.bags[0].name = "Amer  Test"; });
bad("packing-name-bidi", (r) => { r.packingPlan.bags[0].name = "Amer\u202e"; });
bad("packing-name-too-long", (r) => { r.packingPlan.bags[0].name = "x".repeat(33); });
bad("car-missing-on-curbside", (r) => { r.car = null; });
bad("full-registration-not-last-four", (r) => { r.car.registrationLast4 = "AB12CDE"; });
bad("paid-before-created", (r) => { r.paidAt = "2026-11-05T15:00:00Z"; });
bad("invalid-date", (r) => { r.acceptedAt = "2026-13-01T12:00:00Z"; });
bad("noncanonical-order-number", (r) => { r.orderNumber = "0000"; });
bad("unknown-payment-method", (r) => { r.paymentMethod = "credit"; });
bad("duplicate-line-id", (r) => { r.items[1].lineId = r.items[0].lineId; });
bad("self-parent", (r) => { r.items[0].parentLineId = r.items[0].lineId; });
bad("duplicate-meal-slot", (r) => { r.items[0].mealComponents = [{ slot: "side", name: "Fries", quantityPerParent: 1, replacement: false }, { slot: "side", name: "Fries", quantityPerParent: 1, replacement: false }]; });
bad("meal-main-replacement", (r) => { r.items[0].mealComponents = [{ slot: "main", name: "Cruncher", quantityPerParent: 1, replacement: true }]; });
bad("meal-name-normalized-silently", (r) => { r.items[0].mealComponents = [{ slot: "main", name: " Cruncher ", quantityPerParent: 1, replacement: false }]; });
bad("notes-over-contract-limit", (r) => { r.items[0].notes = "x".repeat(20001); });

const destination = new URL("./src/test/resources/receipt-golden.json", import.meta.url);
const expected = JSON.stringify({ source: "tools/receipt-bridge/receipt.mjs", valid, invalid }, null, 2) + "\n";
if (process.argv.includes("--check")) {
  if ((await readFile(destination, "utf8")) !== expected) throw new Error("Native receipt golden fixtures differ from the authoritative JS contract; regenerate and review both implementations.");
  console.log(`Verified ${valid.length} valid and ${invalid.length} invalid native receipt contract cases.`);
} else {
  await mkdir(dirname(fileURLToPath(destination)), { recursive: true });
  await writeFile(destination, expected);
  console.log(`Generated ${valid.length} valid and ${invalid.length} invalid native receipt contract cases.`);
}
